/*
 * Demo page: preference picker, story-style ad player, narration, ratings and
 * the "Why this version?" panel. All choices come from window.Assembler; all
 * copy comes from window.LIBRARY (generated by scripts/check-library.js).
 */
(function () {
  'use strict';

  var LIB = window.LIBRARY;
  var A = window.Assembler;
  var $ = function (id) { return document.getElementById(id); };

  // Embedded in the website (?embed=1): hide the page's own heading and tell the parent page how
  // tall the content is, so the iframe always fits.
  if (new URLSearchParams(location.search).get('embed') === '1') {
    document.body.classList.add('embed');
    if (window.parent !== window && 'ResizeObserver' in window) {
      // Measure the content, not the document: the document is never shorter than the frame itself.
      var postHeight = function () {
        var layout = document.querySelector('.layout');
        var height = Math.ceil(layout ? layout.getBoundingClientRect().height : document.body.scrollHeight);
        window.parent.postMessage({ type: 'agentic-ad-height', height: height }, location.origin);
      };
      new ResizeObserver(postHeight).observe(document.querySelector(".layout") || document.body);
      window.addEventListener('load', postHeight);
    }
  }

  var UI = {
    en: { testimonial: 'From previous cohorts', cta: 'Register your interest' },
    zh: { testimonial: '往期学员评价 · 译文', cta: '登记你的意向' }
  };
  var SITE = 'sasistician.com';
  var GOOD_EN = /Karen|Samantha|Daniel|Moira|Serena|Tessa|Ava|Allison|Susan|Tom|Evan|Zoe|Nicky|Matilda|Lee|Catherine|Gordon|Alex/;
  var NOVELTY = /Albert|Bad News|Bahh|Bells|Boing|Bubbles|Cellos|Wobble|Zarvox|Whisper|Trinoids|Organ|Jester|Superstar|Good News|Hysterical|Ralph|Fred|Junior|Kathy|Grandma|Grandpa|Rocko|Shelley|Flo|Eddy|Reed|Sandy/;
  var GLOWS = [
    ['0%', '0%', '0%', '0%'], ['40%', '20%', '-20%', '-10%'], ['10%', '60%', '-40%', '-50%'],
    ['60%', '50%', '10%', '-30%'], ['20%', '10%', '-30%', '-60%'], ['50%', '70%', '-10%', '0%']
  ];

  // ---------- storage (works even when localStorage is blocked) ----------
  var mem = {};
  var store = {
    get: function (key, fallback) {
      try {
        var raw = localStorage.getItem(key);
        if (raw != null) return JSON.parse(raw);
      } catch (e) { /* fall through to memory */ }
      return key in mem ? mem[key] : fallback;
    },
    set: function (key, value) {
      mem[key] = value;
      try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) { /* memory only */ }
    }
  };

  if (!LIB || !A) {
    renderEmpty();
    return;
  }

  var F = LIB.factors;
  var DIMS = F.personalized;
  // URL parameters (?role=&goal=&industry=&lang=&length=&mode=&variant=&scene=) override saved settings,
  // so a specific version can be bookmarked or screenshotted.
  var params = new URLSearchParams(location.search);
  var state = {
    prefs: loadPrefs(),
    mode: (params.get('mode') || store.get('am.mode', 'yours')) === 'generic' ? 'generic' : 'yours',
    variant: parseInt(params.get('variant') || '0', 10) || 0,
    stillScene: parseInt(params.get('scene') || '0', 10) || 0,
    narration: false,
    hasPlayed: false,
    ad: null,
    token: 0,
    timers: []
  };

  function loadPrefs() {
    var saved = Object.assign({}, store.get('am.prefs', {}) || {});
    params.forEach(function (value, key) {
      if (DIMS.indexOf(key) !== -1 || key === 'lang') saved[key] = value;
      if (key === 'length') saved.length = parseInt(value, 10);
    });
    var prefs = {};
    DIMS.forEach(function (d) {
      var ids = F.factors[d].values.map(function (v) { return v.id; });
      prefs[d] = ids.indexOf(saved[d]) !== -1 ? saved[d] : ids[0];
    });
    prefs.lang = saved.lang === 'zh' ? 'zh' : 'en';
    prefs.length = F.lengths.indexOf(saved.length) !== -1 ? saved.length : 15;
    return prefs;
  }

  function labelFor(dim, id) {
    var v = F.factors[dim].values.filter(function (x) { return x.id === id; })[0];
    return v ? v.en : id;
  }

  // ---------- controls ----------
  function buildSelect(dim) {
    var el = $(dim);
    F.factors[dim].values.forEach(function (v) {
      var o = document.createElement('option');
      o.value = v.id;
      o.textContent = v.en;
      el.appendChild(o);
    });
    el.value = state.prefs[dim];
    el.addEventListener('change', function () { setPref(dim, el.value); });
  }

  function buildSeg(el, options, current, onPick) {
    el.innerHTML = '';
    options.forEach(function (opt) {
      var b = document.createElement('button');
      b.type = 'button';
      b.setAttribute('role', 'radio');
      b.setAttribute('aria-checked', String(opt.value === current));
      b.textContent = opt.label;
      b.addEventListener('click', function () { onPick(opt.value); });
      b.addEventListener('keydown', function (e) {
        if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
        var i = options.indexOf(opt) + (e.key === 'ArrowRight' ? 1 : -1);
        var nextOpt = options[(i + options.length) % options.length];
        onPick(nextOpt.value);
        el.querySelectorAll('button')[options.indexOf(nextOpt)].focus();
      });
      el.appendChild(b);
    });
  }

  function renderSegs() {
    buildSeg($('lang'), F.languages.map(function (l) { return { value: l.id, label: l.label }; }), state.prefs.lang, function (v) { setPref('lang', v); });
    buildSeg($('length'), F.lengths.map(function (n) { return { value: n, label: n + 's' }; }), state.prefs.length, function (v) { setPref('length', v); });
    buildSeg($('mode'), [{ value: 'generic', label: 'Generic' }, { value: 'yours', label: 'Yours' }], state.mode, setMode);
  }

  function setPref(key, value) {
    state.prefs[key] = value;
    store.set('am.prefs', state.prefs);
    state.variant = 0;
    state.stillScene = 0;
    refresh();
  }

  function setMode(mode) {
    state.mode = mode;
    store.set('am.mode', mode);
    state.variant = 0;
    state.stillScene = 0;
    refresh();
  }

  function refresh() {
    renderSegs();
    assemble();
    if (state.hasPlayed) play(); else showStill();
  }

  // ---------- assembling ----------
  function assemble() {
    state.ad = A.assemble(LIB, state.prefs, { mode: state.mode, variant: state.variant });
    state.variant = state.ad.variant;
    var ad = state.ad;
    var info = 'Version ' + (ad.variant + 1) + ' of ' + ad.versionCount + ' · ' + ad.totalSeconds + 's';
    if (ad.missing.length) info += ' · missing: ' + ad.missing.join(', ');
    $('version-info').textContent = info;
    $('another').disabled = ad.versionCount < 2;
    $('caption').textContent = state.mode === 'generic'
      ? 'Generic version: what every viewer would see.'
      : 'Your version, assembled for ' + DIMS.map(function (d) { return labelFor(d, state.prefs[d]); }).join(' · ') + '.';
    renderWhy();
    renderStars();
    updateVoiceNote();
  }

  function renderWhy() {
    var list = $('why-list');
    list.innerHTML = '';
    state.ad.scenes.forEach(function (s) {
      var li = document.createElement('li');
      var slot = el('div', 'slot', s.slot + ' · ' + s.seconds + 's · ' + s.part.id);
      var match;
      if (state.mode === 'generic') match = 'Generic part: everyone sees this.';
      else if (s.matched.length) match = 'Matched your ' + s.matched.map(function (d) { return d + ' (' + labelFor(d, state.prefs[d]) + ')'; }).join(' and ') + '.';
      else match = 'Nothing specific for you in this slot, so the generic part fills it.';
      if (s.alternatives > 1) match += ' ' + s.alternatives + ' parts tied; "Another version" cycles them.';
      li.appendChild(slot);
      li.appendChild(el('div', 'match', match));
      var src = A.citedSources(LIB, s.part);
      if (s.part.kind === 'framing') li.appendChild(el('div', 'src', 'Framing line: makes no factual claim.'));
      src.claims.forEach(function (c) { li.appendChild(el('div', 'src', 'Backed by "' + c.text + '"')); });
      if (src.testimonial) li.appendChild(el('div', 'src', 'Verbatim from ' + src.testimonial.name + ', ' + src.testimonial.role + ' (previous cohort).'));
      list.appendChild(li);
    });
  }

  // ---------- ratings ----------
  function ratings() { return store.get('am.ratings', {}) || {}; }

  function renderStars() {
    var key = A.ratingKey(state.prefs, state.mode, state.variant);
    var current = (ratings()[key] || {}).rating;
    buildSeg($('stars'), [1, 2, 3, 4, 5].map(function (n) { return { value: n, label: String(n) }; }), current, function (n) {
      var all = ratings();
      all[key] = { rating: n, at: new Date().toISOString() };
      store.set('am.ratings', all);
      renderStars();
    });
    var s = A.summarizeRatings(ratings());
    var fmt = function (m) { return s[m].n ? s[m].avg.toFixed(1) + ' (' + s[m].n + ')' : 'none yet'; };
    $('rating-summary').textContent = (s.generic.n || s.yours.n)
      ? 'Your average: generic ' + fmt('generic') + ' · yours ' + fmt('yours')
      : 'Rate a few generic and personalized versions to compare.';
  }

  $('export').addEventListener('click', function () {
    var payload = { exportedAt: new Date().toISOString(), summary: A.summarizeRatings(ratings()), ratings: ratings() };
    var blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'ad-ratings.json';
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 0);
  });

  // ---------- narration ----------
  var synth = 'speechSynthesis' in window ? window.speechSynthesis : null;

  // Natural-sounding voices first: Apple Premium/Enhanced, then Chrome's Google
  // voices, then the better compact voices. Locale only breaks ties.
  function voiceScore(v, lang) {
    var s = 0;
    if (/Premium/.test(v.name)) s += 40;
    else if (/Enhanced/.test(v.name)) s += 30;
    if (/^Google/.test(v.name)) s += 20;
    if (lang === 'en' && GOOD_EN.test(v.name)) s += 5;
    var locales = lang === 'zh' ? ['zh-CN', 'zh-TW', 'zh-HK'] : ['en-US', 'en-GB', 'en-AU'];
    var i = locales.indexOf(v.lang.replace('_', '-'));
    return s + (i === -1 ? 0 : 3 - i);
  }

  function voicesFor(lang) {
    if (!synth) return [];
    return synth.getVoices()
      .filter(function (v) { return !NOVELTY.test(v.name) && v.lang.replace('_', '-').indexOf(lang) === 0; })
      .sort(function (a, b) { return voiceScore(b, lang) - voiceScore(a, lang) || a.name.localeCompare(b.name); });
  }

  // Recorded voices (demo/audio/manifest.js, made by scripts/render-voice.py) come first;
  // browser voices are the fallback, as in a voice agent's TTS_BACKEND=system mode.
  var VM = window.VOICE_MANIFEST || null;

  // Only voices with every line recorded, so an ad never switches voice halfway through
  // (e.g. a Groq voice cut short by the free tier's daily limit).
  function recordedVoices(lang) {
    if (!VM) return [];
    return VM.voices.filter(function (v) { return v.lang === lang && VM.clips[v.id] && v.complete !== false; });
  }

  function voiceOptions(lang) {
    var opts = recordedVoices(lang).map(function (v) { return { value: 'rec:' + v.id, label: v.label }; });
    voicesFor(lang).forEach(function (v) { opts.push({ value: 'sys:' + v.name, label: 'Browser: ' + v.name }); });
    return opts;
  }

  // The chosen option value ("rec:<voice id>" or "sys:<browser voice name>"), or null.
  function chosenVoice(lang) {
    var opts = voiceOptions(lang);
    var saved = (store.get('am.voice', {}) || {})[lang];
    if (saved && saved.indexOf(':') === -1) saved = 'sys:' + saved; // older saved format
    var match = opts.filter(function (o) { return o.value === saved; })[0];
    return (match || opts[0] || { value: null }).value;
  }

  function systemVoice(lang, name) {
    var list = voicesFor(lang);
    return list.filter(function (v) { return v.name === name; })[0] || list[0] || null;
  }

  function renderVoicePicker() {
    var sel = $('voice');
    var lang = state.prefs.lang;
    var opts = voiceOptions(lang);
    sel.innerHTML = '';
    opts.forEach(function (opt) {
      var o = document.createElement('option');
      o.value = opt.value;
      o.textContent = opt.label;
      sel.appendChild(o);
    });
    var current = chosenVoice(lang);
    if (current) sel.value = current;
    sel.closest('.field').hidden = opts.length < 2;
  }

  $('voice').addEventListener('change', function () {
    var saved = store.get('am.voice', {}) || {};
    saved[state.prefs.lang] = this.value;
    store.set('am.voice', saved);
    if (state.narration) { // preview the new voice on the current ad's first line
      stopAudio();
      var scene = state.ad.scenes[0];
      if (scene) speak(scene.part, function () {});
    }
  });

  function updateVoiceNote() {
    var note = $('voice-note');
    var btn = $('narration');
    renderVoicePicker();
    var available = !!chosenVoice(state.prefs.lang);
    btn.disabled = !available;
    note.hidden = available;
    if (!available) {
      note.textContent = state.prefs.lang === 'zh'
        ? 'No Mandarin voice available. Run scripts/render-voice.py, or add a system voice in System Settings → Accessibility → Spoken Content.'
        : 'No English voice available for narration.';
    }
  }
  if (synth) synth.addEventListener('voiceschanged', updateVoiceNote);

  $('narration').addEventListener('click', function () {
    state.narration = !state.narration;
    this.setAttribute('aria-pressed', String(state.narration));
    this.textContent = 'Narration: ' + (state.narration ? 'on' : 'off');
    if (!state.narration) stopAudio();
  });

  function stopAudio() {
    if (state.audio) { state.audio.pause(); state.audio = null; }
    if (synth) synth.cancel();
  }

  function speak(part, done) {
    var lang = state.prefs.lang;
    var choice = chosenVoice(lang);
    var finished = false;
    var finish = function () { if (!finished) { finished = true; done(); } };
    state.timers.push(setTimeout(finish, 15000)); // never let a stuck voice hold the ad
    if (choice && choice.indexOf('rec:') === 0) {
      var clip = (VM.clips[choice.slice(4)] || {})[part.id];
      if (clip) {
        var audio = new Audio(clip.file);
        var fallback = function () { if (state.audio === audio) speakSystem(part, lang, null, finish); };
        state.audio = audio;
        audio.onended = finish;
        audio.onerror = fallback;
        var playing = audio.play();
        if (playing && playing.catch) playing.catch(fallback);
        return;
      }
      choice = null; // no recording for this part: use the best browser voice
    }
    speakSystem(part, lang, choice ? choice.slice(4) : null, finish);
  }

  function speakSystem(part, lang, name, finish) {
    var voice = systemVoice(lang, name);
    var t = part.text[lang] || {};
    var text = (part.narration && part.narration[lang]) || [t.headline, t.sub].filter(Boolean).join('. ');
    if (!synth || !voice || !text) { finish(); return; }
    var u = new SpeechSynthesisUtterance(text);
    u.voice = voice;
    u.lang = voice.lang;
    u.onend = finish;
    u.onerror = finish;
    synth.speak(u);
  }

  // ---------- playback ----------
  function clearTimers() {
    state.timers.forEach(clearTimeout);
    state.timers = [];
  }

  function stop() {
    state.token++;
    clearTimers();
    stopAudio();
  }

  function play() {
    stop();
    state.hasPlayed = true;
    $('play').textContent = 'Replay';
    var my = state.token;
    var scenes = state.ad.scenes;
    var i = 0;
    function next() {
      if (my !== state.token || i >= scenes.length) return;
      var scene = scenes[i];
      showScene(i, true);
      var timeDone = false;
      var speechDone = !state.narration;
      var advance = function () {
        if (my !== state.token || !timeDone || !speechDone) return;
        i++;
        next();
      };
      state.timers.push(setTimeout(function () { timeDone = true; advance(); }, scene.seconds * 1000));
      if (state.narration) speak(scene.part, function () { speechDone = true; state.timers.push(setTimeout(advance, 300)); });
    }
    next();
  }

  $('play').addEventListener('click', play);
  $('another').addEventListener('click', function () {
    state.variant = state.variant + 1;
    state.stillScene = 0;
    refresh();
  });

  function showStill() {
    stop();
    showScene(Math.min(state.stillScene, state.ad.scenes.length - 1), false);
  }

  // ---------- rendering ----------
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }

  // Splits text into word/character spans that rise in one after another.
  // Closing punctuation sticks to the token before it, so a line never starts
  // with "。" or "，" (each span is inline-block, which defeats the browser's
  // own line-breaking rules for CJK punctuation).
  var TOKEN = /(?:[A-Za-z0-9][A-Za-z0-9’'\-.]*|[“‘「『（(]*[^\s])[，。、；：？！）」』”’…,.?!:;)]*|\s+/gu;
  function animated(tag, cls, text, lang, startDelay) {
    var n = el(tag, cls);
    var tokens = String(text).match(TOKEN) || [];
    var step = lang === 'zh' ? 0.035 : 0.06;
    var k = 0;
    tokens.forEach(function (tok) {
      if (/^\s+$/.test(tok)) { n.appendChild(document.createTextNode(' ')); return; }
      var s = el('span', 'w', tok);
      s.style.animationDelay = (startDelay + k * step).toFixed(2) + 's';
      k++;
      n.appendChild(s);
    });
    return n;
  }

  function fadeIn(node, delay) {
    node.classList.add('fade');
    node.style.animationDelay = delay.toFixed(2) + 's';
    return node;
  }

  function sizeClass(text, lang) {
    var n = [].concat(Array.from(String(text))).length;
    if (lang === 'zh') return n > 34 ? ' xlong' : n > 22 ? ' long' : '';
    return n > 80 ? ' xlong' : n > 48 ? ' long' : '';
  }

  function weekOf(part) {
    var badge = (part.text.en && part.text.en.badge) || '';
    var m = badge.match(/\d+/) || (part.claims || []).join(' ').match(/week-0(\d)/);
    var n = m ? parseInt(m[1] || m[0], 10) : 0;
    return n >= 1 && n <= 5 ? n : 0;
  }

  function renderBars(active, animate, seconds) {
    var bars = $('bars');
    bars.innerHTML = '';
    state.ad.scenes.forEach(function (s, i) {
      var span = el('span', i < active ? 'done' : '');
      var fill = el('i');
      span.appendChild(fill);
      bars.appendChild(span);
      if (i === active && animate) {
        requestAnimationFrame(function () {
          requestAnimationFrame(function () {
            fill.style.transition = 'width ' + seconds + 's linear';
            fill.style.width = '100%';
          });
        });
      }
    });
  }

  function showScene(index, animate) {
    var scene = state.ad.scenes[index];
    var root = $('scene');
    root.innerHTML = '';
    if (!scene) {
      root.appendChild(el('p', 'empty', 'No parts available for this combination.'));
      return;
    }
    renderBars(index, animate, scene.seconds);
    var g = GLOWS[index % GLOWS.length];
    var card = $('card');
    card.style.setProperty('--ax', g[0]); card.style.setProperty('--ay', g[1]);
    card.style.setProperty('--bx', g[2]); card.style.setProperty('--by', g[3]);

    var lang = state.prefs.lang;
    root.setAttribute('lang', lang);
    var part = scene.part;
    var t = part.text[lang] || part.text.en;
    var head = function (text, delay) { return animated('h2', 'headline' + sizeClass(text, lang), text, lang, delay); };

    switch (part.visual) {
      case 'shift':
        root.appendChild(fadeIn(el('p', 'before', t.headline), 0.1));
        root.appendChild(fadeIn(el('div', 'arrow', '↓'), 0.6));
        root.appendChild(head(t.sub || '', 0.9));
        break;
      case 'weeks': {
        if (t.badge) root.appendChild(fadeIn(el('span', 'pill', t.badge), 0.05));
        var row = el('div', 'weeks');
        var w = weekOf(part);
        for (var n = 1; n <= 5; n++) row.appendChild(el('span', n === w ? 'on' : '', '0' + n));
        root.appendChild(fadeIn(row, 0.2));
        root.appendChild(head(t.headline, 0.4));
        if (t.sub) root.appendChild(fadeIn(el('p', 'sub', t.sub), 1.0));
        break;
      }
      case 'portrait': {
        var img = el('img', 'portrait');
        img.src = 'assets/bilal-farooq.jpg';
        img.alt = 'Bilal Farooq';
        img.onerror = function () { img.remove(); };
        root.appendChild(fadeIn(img, 0.05));
        root.appendChild(fadeIn(el('p', 'who', 'Bilal Farooq'), 0.3));
        root.appendChild(head(t.headline, 0.5));
        if (t.sub) root.appendChild(fadeIn(el('p', 'sub', t.sub), 1.1));
        break;
      }
      case 'quote': {
        var src = A.citedSources(LIB, part).testimonial;
        var qc = el('div', 'quote-card');
        qc.appendChild(el('div', 'quote-mark', '“'));
        qc.appendChild(head(t.headline, 0.2));
        if (src) {
          var at = el('p', 'attrib');
          at.appendChild(el('b', null, src.name));
          at.appendChild(document.createTextNode(', ' + src.role + ' · ' + UI[lang].testimonial));
          qc.appendChild(fadeIn(at, 1.0));
        }
        root.appendChild(fadeIn(qc, 0.05));
        break;
      }
      case 'cta':
        root.appendChild(head(t.headline, 0.1));
        if (t.sub) root.appendChild(fadeIn(el('p', 'sub', t.sub), 0.7));
        root.appendChild(fadeIn(el('div', 'cta-btn', UI[lang].cta), 1.0));
        root.appendChild(fadeIn(el('p', 'url', SITE), 1.3));
        break;
      default: // statement, question
        if (t.badge) root.appendChild(fadeIn(el('span', 'pill', t.badge), 0.05));
        root.appendChild(head(t.headline, 0.15));
        if (t.sub) root.appendChild(fadeIn(el('p', 'sub', t.sub), 0.9));
    }
  }

  function renderEmpty() {
    var root = document.getElementById('scene');
    if (root) {
      root.innerHTML = '';
      var p = document.createElement('p');
      p.className = 'empty';
      p.innerHTML = 'The ad library hasn’t been built yet.<br><br>In Claude Code, run <code>/build-library</code>, then reload this page.';
      root.appendChild(p);
    }
    document.querySelectorAll('.field, .actions, .rating, details').forEach(function (n) { n.hidden = true; });
  }

  // ---------- start ----------
  DIMS.forEach(buildSelect);
  if (F.languages.length < 2) $('lang').closest('.field').hidden = true;
  if (params.get('why') === '1') $('why').open = true;
  refresh();
  if (params.get('autoplay') === '1') play();
})();
